import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'
import type { ChangeEvent } from 'react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { DEFAULT_CARD_TYPES, DEFAULT_STATES } from '../../../data/data_types'
import { AppThemeProvider } from '../../../theme/theme_provider'
import { NewCardDialog } from './new_card_dialog'
import { projectSessionService } from '../../../services/project/project_session_service'
import { dialogService } from '../../../services/dialog_service'
import type { MarkdownDraft } from '../../../services/markdown/markdown_draft'

const { editorBoundaryRender } = vi.hoisted(() => ({ editorBoundaryRender: vi.fn() }))

vi.mock('./new_card_markdown_editor', () => {
    interface EditorProps {
        draft: MarkdownDraft
    }

    function NewCardMarkdownEditor(props: EditorProps) {
        editorBoundaryRender()

        const handleChange = (event: ChangeEvent<HTMLTextAreaElement>) => {
            props.draft.edit(event.currentTarget.value)
        }

        return <textarea aria-label="Draft body" defaultValue={props.draft.getSnapshot()} onChange={handleChange} />
    }

    return { NewCardMarkdownEditor }
})

describe('NewCardDialog editor render boundary', () => {
    afterEach(() => {
        cleanup()
        projectSessionService.newCardMarkdownDraft.replace('')
        vi.restoreAllMocks()
    })

    it('does not rerender the editor boundary for repeated description edits', () => {
        window.matchMedia = ((query: string) => ({
            addEventListener: () => {},
            addListener: () => {},
            dispatchEvent: () => false,
            matches: false,
            media: query,
            onchange: null,
            removeEventListener: () => {},
            removeListener: () => {},
        })) as unknown as typeof window.matchMedia

        render(
            <NewCardDialog
                cardTypes={DEFAULT_CARD_TYPES}
                initialTargetStatus="new"
                isLoading={false}
                isProjectOpen
                onClose={vi.fn()}
                onCreateCard={vi.fn(async () => undefined)}
                open
                states={DEFAULT_STATES}
            />,
            { wrapper: AppThemeProvider },
        )

        const description = within(screen.getByRole('group', { name: 'Description' })).getByRole('textbox')
        const initialRenderCount = editorBoundaryRender.mock.calls.length
        fireEvent.change(description, { target: { value: 'One' } })
        fireEvent.change(description, { target: { value: 'One two' } })
        fireEvent.change(description, { target: { value: 'One two three' } })

        expect(editorBoundaryRender).toHaveBeenCalledTimes(initialRenderCount)
    })

    it('keeps footer attachment before Add to and retains body after editor unmount', () => {
        window.matchMedia = ((query: string) => ({
            addEventListener: () => {}, addListener: () => {}, dispatchEvent: () => false, matches: false,
            media: query, onchange: null, removeEventListener: () => {}, removeListener: () => {},
        })) as unknown as typeof window.matchMedia
        const view = render(
            <NewCardDialog
                cardTypes={DEFAULT_CARD_TYPES}
                initialTargetStatus="new"
                isLoading={false}
                isProjectOpen
                onClose={vi.fn()}
                onCreateCard={vi.fn(async () => undefined)}
                open
                states={DEFAULT_STATES}
            />,
            { wrapper: AppThemeProvider },
        )
        const startGroup = screen.getByTestId('new-card-footer-start')
        const attachment = within(startGroup).getByRole('button', { name: 'Attach files' })
        const targetColumn = within(startGroup).getByRole('combobox', { name: 'Target column' })

        expect(attachment.compareDocumentPosition(targetColumn) & Node.DOCUMENT_POSITION_FOLLOWING).not.toBe(0)
        fireEvent.change(screen.getByRole('textbox', { name: 'Draft body' }), { target: { value: 'Persistent body' } })
        view.unmount()
        expect(projectSessionService.newCardMarkdownDraft.getSnapshot()).toBe('Persistent body')
    })

    it('keeps attachment and Add to in the mobile footer without a second create control', () => {
        window.matchMedia = ((query: string) => ({
            addEventListener: () => {}, addListener: () => {}, dispatchEvent: () => false, matches: true,
            media: query, onchange: null, removeEventListener: () => {}, removeListener: () => {},
        })) as unknown as typeof window.matchMedia
        render(
            <NewCardDialog
                cardTypes={DEFAULT_CARD_TYPES}
                initialTargetStatus="new"
                isLoading={false}
                isProjectOpen
                onClose={vi.fn()}
                onCreateCard={vi.fn(async () => undefined)}
                open
                states={DEFAULT_STATES}
            />,
            { wrapper: AppThemeProvider },
        )
        const startGroup = screen.getByTestId('new-card-footer-start')
        const footer = startGroup.parentElement as HTMLElement
        const targetColumn = within(startGroup).getByRole('combobox', { name: 'Target column' })

        expect(startGroup).toHaveStyle({ display: 'flex', flexDirection: 'row', width: '100%' })
        expect(targetColumn.parentElement).toHaveStyle({ flex: '1 1 0%', minWidth: '0' })
        expect(within(footer).queryByRole('button', { name: /Create/u })).toBeNull()
        expect(screen.getAllByRole('button', { name: 'Create' })).toHaveLength(1)
    })

    it('waits for draft image cleanup before confirmed cancellation closes the dialog', async () => {
        window.matchMedia = ((query: string) => ({
            addEventListener: () => {}, addListener: () => {}, dispatchEvent: () => false, matches: false,
            media: query, onchange: null, removeEventListener: () => {}, removeListener: () => {},
        })) as unknown as typeof window.matchMedia
        let resolveCleanup: () => void = () => undefined
        const cleanup = new Promise<void>((resolve) => { resolveCleanup = resolve })
        vi.spyOn(projectSessionService, 'hasNewCardDraftImages').mockReturnValue(true)
        vi.spyOn(projectSessionService, 'discardNewCardDraftImages').mockReturnValue(cleanup)
        vi.spyOn(window, 'confirm').mockReturnValue(true)
        const onClose = vi.fn()
        render(
            <NewCardDialog
                cardTypes={DEFAULT_CARD_TYPES}
                initialTargetStatus="new"
                isLoading={false}
                isProjectOpen
                onClose={onClose}
                onCreateCard={vi.fn(async () => undefined)}
                open
                states={DEFAULT_STATES}
            />,
            { wrapper: AppThemeProvider },
        )

        fireEvent.click(screen.getByRole('button', { name: 'Cancel' }))
        expect(onClose).not.toHaveBeenCalled()

        resolveCleanup()
        await waitFor(() => expect(onClose).toHaveBeenCalledOnce())
    })

    it('keeps the draft open and reports failed cancellation cleanup', async () => {
        window.matchMedia = ((query: string) => ({
            addEventListener: () => {}, addListener: () => {}, dispatchEvent: () => false, matches: false,
            media: query, onchange: null, removeEventListener: () => {}, removeListener: () => {},
        })) as unknown as typeof window.matchMedia
        const cleanupError = new Error('delete failed')
        vi.spyOn(projectSessionService, 'hasNewCardDraftImages').mockReturnValue(true)
        vi.spyOn(projectSessionService, 'discardNewCardDraftImages').mockRejectedValue(cleanupError)
        vi.spyOn(window, 'confirm').mockReturnValue(true)
        const reportError = vi.spyOn(dialogService, 'error')
        const onClose = vi.fn()
        render(
            <NewCardDialog
                cardTypes={DEFAULT_CARD_TYPES}
                initialTargetStatus="new"
                isLoading={false}
                isProjectOpen
                onClose={onClose}
                onCreateCard={vi.fn(async () => undefined)}
                open
                states={DEFAULT_STATES}
            />,
            { wrapper: AppThemeProvider },
        )

        fireEvent.click(screen.getByRole('button', { name: 'Cancel' }))

        await waitFor(() => expect(reportError).toHaveBeenCalledWith(
            cleanupError,
            { fallbackMessage: 'Pasted draft images could not be removed' },
        ))
        expect(onClose).not.toHaveBeenCalled()
    })

    it('waits for image insertion before reading the draft body for creation', async () => {
        window.matchMedia = ((query: string) => ({
            addEventListener: () => {}, addListener: () => {}, dispatchEvent: () => false, matches: false,
            media: query, onchange: null, removeEventListener: () => {}, removeListener: () => {},
        })) as unknown as typeof window.matchMedia
        let resolveImageSave: () => void = () => undefined
        const imageSave = new Promise<void>((resolve) => { resolveImageSave = resolve })
        vi.spyOn(projectSessionService, 'waitForNewCardImageSaves').mockReturnValue(imageSave)
        const onCreateCard = vi.fn(async () => undefined)
        render(
            <NewCardDialog
                cardTypes={DEFAULT_CARD_TYPES}
                initialTargetStatus="new"
                isLoading={false}
                isProjectOpen
                onClose={vi.fn()}
                onCreateCard={onCreateCard}
                open
                states={DEFAULT_STATES}
            />,
            { wrapper: AppThemeProvider },
        )

        fireEvent.change(screen.getByRole('textbox', { name: 'Title' }), { target: { value: 'Image card' } })
        fireEvent.click(screen.getByRole('button', { name: 'Create card' }))
        expect(onCreateCard).not.toHaveBeenCalled()

        fireEvent.change(screen.getByRole('textbox', { name: 'Draft body' }), {target: { value: '![pasted image](<saved.png>)' }})
        resolveImageSave()

        await waitFor(() => expect(onCreateCard).toHaveBeenCalledWith({
            body: '![pasted image](<saved.png>)',
            title: 'Image card',
            type: 'feature',
        }, 'new'))
    })
})

import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Stack,
    TextField,
    Tooltip,
    Typography,
    useMediaQuery,
    useTheme,
} from '@mui/material'
import Close from 'mdi-material-ui/Close'
import Plus from 'mdi-material-ui/Plus'
import type { ChangeEvent, FormEvent, KeyboardEvent } from 'react'
import { useEffect, useRef, useState } from 'react'
import type { CardDraft, CardTypeConfig, StateConfig } from '../../../data/data_types'
import { useCardCreationState } from '../../hooks/use_card_creation_state'
import { CardTypePillGroup } from './card_type_pill_group'
import { NewCardMarkdownEditor } from './new_card_markdown_editor'
import { projectSessionService } from '../../../services/project/project_session_service'
import { dialogService } from '../../../services/dialog_service'
import { NewCardColumnPicker } from './new_card_column_picker'
import { MarkdownAttachmentControl } from '../../editor/markdown_attachment_control'
import { attachFilesToNewCardMarkdown } from '../../../services/attachments/new_card_attachment_workflow'

const DIALOG_WIDTH = 480
const DISCARD_CARD_MESSAGE = 'Discard this new card draft?'

function attachFilesToNewCardDraft(files: File[]) {
    void attachFilesToNewCardMarkdown(files, projectSessionService.newCardMarkdownDraft.requestInsertion).catch((error: unknown) => {
        dialogService.error(error, { fallbackMessage: 'Files could not be attached' })
    })
}

interface NewCardDialogProps {
    cardTypes: CardTypeConfig[]
    initialTargetStatus: string
    isLoading: boolean
    isProjectOpen: boolean
    open: boolean
    onClose: () => void
    onCreateCard: (draft: CardDraft, initialState: string) => Promise<void>
    states: StateConfig[]
}

/** Responsive form for creating a card in a selected board column. */
export function NewCardDialog(props: NewCardDialogProps) {
    const {
        cardTypes,
        initialTargetStatus,
        isLoading,
        isProjectOpen,
        onClose,
        onCreateCard,
        open,
        states,
    } = props
    const { isCreatingCard } = useCardCreationState()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const cancellationInProgressRef = useRef(false)
    const wasOpenRef = useRef(false)
    const [targetStatus, setTargetStatus] = useState('')
    const [title, setTitle] = useState('')
    const [type, setType] = useState('')
    const defaultType = cardTypes[0]?.type ?? ''
    const defaultStatus = states[0]?.state ?? ''
    const selectedType = cardTypes.some((typeConfig) => typeConfig.type === type) ? type : defaultType
    const selectedStatus = states.some((stateConfig) => stateConfig.state === targetStatus) ? targetStatus : defaultStatus
    const isSubmitDisabled = !isProjectOpen || title.trim().length === 0
        || selectedType.length === 0 || selectedStatus.length === 0 || isLoading || isCreatingCard

    const resetForm = () => {
        projectSessionService.newCardMarkdownDraft.replace('')
        setTargetStatus(initialTargetStatus)
        setTitle('')
        setType(defaultType)
    }

    useEffect(() => {
        if ((open && !wasOpenRef.current) || !isProjectOpen) {
            projectSessionService.newCardMarkdownDraft.replace('')
            setTargetStatus(initialTargetStatus)
            setTitle('')
            setType(defaultType)
        }
        wasOpenRef.current = open && isProjectOpen
    }, [defaultType, initialTargetStatus, isProjectOpen, open])

    const closeDialog = async () => {
        if (cancellationInProgressRef.current) return

        cancellationInProgressRef.current = true
        try {
            const body = projectSessionService.newCardMarkdownDraft.getSnapshot()
            const isDirty = title.length > 0
                || body.length > 0
                || selectedType !== defaultType
                || selectedStatus !== initialTargetStatus
                || projectSessionService.hasNewCardDraftImages()
            if (isDirty && !window.confirm(DISCARD_CARD_MESSAGE)) return

            try {
                await projectSessionService.discardNewCardDraftImages()
            } catch (error) {
                dialogService.error(error, { fallbackMessage: 'Pasted draft images could not be removed' })
                return
            }
            resetForm()
            onClose()
        } finally {
            cancellationInProgressRef.current = false
        }
    }

    const handleDialogClose = () => {
        void closeDialog()
    }

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setTitle(event.target.value)
    }

    const handleCreateClick = async () => {
        if (isSubmitDisabled) return

        await projectSessionService.waitForNewCardImageSaves()
        const body = projectSessionService.newCardMarkdownDraft.getSnapshot()
        const draft: CardDraft = {
            body,
            title: title.trim(),
            type: selectedType,
        }
        try {
            await onCreateCard(draft, selectedStatus)
        } catch {
            return
        }
        resetForm()
    }

    const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault()
        await handleCreateClick()
    }

    const handleFormKeyDownCapture = (event: KeyboardEvent<HTMLFormElement>) => {
        if (event.key !== 'Enter' || !event.ctrlKey) return

        event.preventDefault()
        event.stopPropagation()
        void handleCreateClick()
    }

    const createButton = (
        <Button aria-label="Create card" disabled={isSubmitDisabled} type="submit" variant="contained">
            <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                <Plus sx={{ fontSize: 17 }} />
                <span>Add</span>
                {!isMobile ? (
                    <Box
                        component="span"
                        sx={{
                            bgcolor: 'rgba(255,255,255,0.18)',
                            borderRadius: '5px',
                            fontSize: 10.5,
                            fontWeight: 600,
                            px: 0.625,
                            py: 0.25,
                        }}
                    >
                        Ctrl+â†µ
                    </Box>
                ) : null}
            </Stack>
        </Button>
    )

    return (
        <Dialog
            aria-labelledby="new-card-dialog-heading"
            fullScreen={isMobile}
            maxWidth={false}
            onClose={handleDialogClose}
            open={open}
            slotProps={{
                backdrop: { sx: { backdropFilter: 'blur(2px)', backgroundColor: 'rgba(16, 24, 40, 0.45)' } },
                paper: {
                    sx: {
                        border: isMobile ? 0 : 1,
                        borderColor: 'divider',
                        borderRadius: isMobile ? 0 : '14px',
                        boxShadow: isMobile ? 'none' : '0 24px 60px rgba(16,24,40,0.28)',
                        height: isMobile ? '100dvh' : 'auto',
                        maxHeight: isMobile ? '100dvh' : 'calc(100dvh - 32px)',
                        maxWidth: isMobile ? '100%' : 'calc(100% - 32px)',
                        overflow: 'hidden',
                        width: isMobile ? '100%' : DIALOG_WIDTH,
                    },
                },
            }}
        >
            <Box
                component="form"
                onKeyDownCapture={handleFormKeyDownCapture}
                onSubmit={handleSubmit}
                sx={{ display: 'flex', flexDirection: 'column', height: isMobile ? '100%' : 'auto', maxHeight: '100dvh', minHeight: 0 }}
            >
                <DialogTitle
                    component="div"
                    id="new-card-dialog-header"
                    sx={{
                        alignItems: 'center',
                        borderBottom: 1,
                        borderColor: 'divider',
                        display: 'flex',
                        flexShrink: 0,
                        gap: 1.25,
                        minHeight: isMobile ? 56 : 62,
                        px: isMobile ? 1 : 2.25,
                        py: 1,
                    }}
                >
                    {isMobile ? (
                        <Button onClick={handleDialogClose} sx={{ minHeight: 44, minWidth: 72 }} type="button" variant="text">
                            Cancel
                        </Button>
                    ) : (
                        <Box
                            sx={{
                                alignItems: 'center',
                                bgcolor: 'custom.primaryBg',
                                borderRadius: 1,
                                color: 'primary.main',
                                display: 'flex',
                                height: 30,
                                justifyContent: 'center',
                                width: 30,
                            }}
                        >
                            <Plus sx={{ fontSize: 18 }} />
                        </Box>
                    )}
                    <Typography
                        component="h2"
                        id="new-card-dialog-heading"
                        sx={{
                            flex: 1,
                            fontSize: isMobile ? 16 : 15.5,
                            fontWeight: 700,
                            textAlign: isMobile ? 'center' : 'left',
                        }}
                    >
                        New card
                    </Typography>
                    {isMobile ? (
                        <Button disabled={isSubmitDisabled} sx={{ minHeight: 44, minWidth: 72 }} type="submit" variant="text">
                            Create
                        </Button>
                    ) : (
                        <Tooltip title="Close">
                            <IconButton aria-label="Close" onClick={handleDialogClose} size="small" sx={{ height: 30, width: 30 }}>
                                <Close sx={{ fontSize: 17 }} />
                            </IconButton>
                        </Tooltip>
                    )}
                </DialogTitle>
                <DialogContent
                    data-testid="new-card-dialog-content"
                    sx={{
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'column',
                        gap: isMobile ? 2.25 : 2,
                        minHeight: 0,
                        overflowY: 'auto',
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 2.25 : 2.25,
                    }}
                >
                    <TextField
                        autoFocus
                        fullWidth
                        id="new-card-title"
                        onChange={handleTitleChange}
                        placeholder="Card titleâ€¦"
                        slotProps={{ htmlInput: { 'aria-label': 'Title' } }}
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                borderRadius: isMobile ? '11px' : '9px',
                                mt: 1,
                                height: isMobile ? 48 : 46,
                                '&.Mui-focused': { boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}` },
                                '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderWidth: 1 },
                                '& .MuiOutlinedInput-notchedOutline': { borderColor: 'custom.borderStrong' },
                            },
                            '& input': {
                                fontSize: isMobile ? 18 : 17,
                                fontWeight: 600,
                            },
                        }}
                        value={title}
                        variant="outlined"
                    />
                    <CardTypePillGroup
                        cardTypes={cardTypes}
                        isMobile={isMobile}
                        onChange={setType}
                        selectedType={selectedType}
                    />
                    <Stack spacing={isMobile ? 1.125 : 0.875}>
                        {!isMobile ? (
                            <Typography color="custom.text3" sx={{ fontSize: 11.5 }}>
                                Markdown
                            </Typography>
                        ) : null}
                        <Box
                            aria-label="Description"
                            data-testid="new-card-description"
                            role="group"
                            sx={{
                                bgcolor: 'background.paper',
                                border: 1,
                                borderColor: 'custom.borderStrong',
                                borderRadius: isMobile ? '11px' : '9px',
                                boxSizing: 'border-box',
                                color: 'text.primary',
                                height: isMobile ? 260 : 270,
                                minHeight: isMobile ? 260 : 270,
                                outline: 'none',
                                overflow: 'auto',
                                resize: isMobile ? 'none' : 'vertical',
                                width: '100%',
                                '&:focus-within': {
                                    borderColor: 'primary.main',
                                    boxShadow: (currentTheme) => `0 0 0 3px ${currentTheme.palette.custom.primaryBg}`,
                                },
                                '&:hover:not(:focus-within)': { borderColor: 'custom.borderHover' },
                                '& > [data-sticky-toolbar]': { minHeight: '100%' },
                                '& .light-theme, & .dark-theme': { minHeight: '100%' },
                                '& .mdxeditor-content': {
                                    boxSizing: 'border-box',
                                    minHeight: isMobile ? 258 : 268,
                                    p: 1.625,
                                },
                            }}
                        >
                            <NewCardMarkdownEditor draft={projectSessionService.newCardMarkdownDraft} />
                        </Box>
                    </Stack>
                </DialogContent>
                <DialogActions
                    sx={{
                        alignItems: 'stretch',
                        bgcolor: 'background.default',
                        borderTop: 1,
                        borderColor: 'divider',
                        flexDirection: isMobile ? 'column' : 'row',
                        flexShrink: 0,
                        gap: isMobile ? 1.5 : 1,
                        justifyContent: 'space-between',
                        m: 0,
                        px: isMobile ? 2 : 2.25,
                        py: isMobile ? 1.5 : 1.5,
                        pb: isMobile ? 'max(12px, env(safe-area-inset-bottom))' : 1.5,
                    }}
                >
                    <Stack
                        data-testid="new-card-footer-start"
                        direction="row"
                        spacing={1}
                        sx={{ alignItems: 'center', minWidth: 0, width: isMobile ? '100%' : 'auto' }}
                    >
                        <MarkdownAttachmentControl disabled={false} onFiles={attachFilesToNewCardDraft} />
                        <NewCardColumnPicker
                            isMobile={isMobile}
                            onChange={setTargetStatus}
                            selectedStatus={selectedStatus}
                            states={states}
                        />
                    </Stack>
                    {!isMobile ? (
                        <Stack direction="row" spacing={1}>
                            <Button onClick={handleDialogClose} type="button" variant="outlined">
                                Cancel
                            </Button>
                            {createButton}
                        </Stack>
                    ) : null}
                </DialogActions>
            </Box>
        </Dialog>
    )
}

import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_STATES,
    type BranchReference,
    type ProjectReference,
    type RepositoryReference,
} from '../../../data/data_types'
import {
    configureRemoteControlConnection,
    REMOTE_CONTROL_ENDPOINT_KEY,
} from '../../../data/remote_control_connection'
import { AppThemeProvider } from '../../../theme/theme_provider'
import { BranchSwitchDialog } from './branch_switch_dialog'
import { CompleteReleaseDialog } from './complete_release_dialog'
import { NewCardDialog } from './new_card_dialog'
import { ProjectOpenDialog } from './project_open_dialog'
import { WorkingFolderChooserDialog } from './working_folder_chooser_dialog'

const BRANCHES: BranchReference[] = [{ name: 'main' }]
const PROJECT: ProjectReference = { branch: 'main', id: 'local', rootPath: 'C:/repo' }
const REPOSITORIES: RepositoryReference[] = [{ branch: 'main', id: 'octo/demo', owner: 'octo', repository: 'demo' }]

function mockMatchMedia(matches: boolean) {
    window.matchMedia = ((query: string) => ({
        addEventListener: () => {},
        addListener: () => {},
        dispatchEvent: () => false,
        matches,
        media: query,
        onchange: null,
        removeEventListener: () => {},
        removeListener: () => {},
    })) as unknown as typeof window.matchMedia
}

function getDescriptionEditor() {
    return within(screen.getByRole('group', { name: 'Description' })).getByRole('textbox')
}

function insertEditorNewline(event: Event) {
    const keyboardEvent = event as globalThis.KeyboardEvent
    if (keyboardEvent.key !== 'Enter') return

    const editor = event.currentTarget as HTMLTextAreaElement
    fireEvent.change(editor, { target: { value: `${editor.value}\n` } })
}

describe('project dialog components', () => {
    beforeEach(() => {
        mockMatchMedia(false)
    })

    afterEach(() => {
        cleanup()
        vi.restoreAllMocks()
        window.localStorage.removeItem(REMOTE_CONTROL_ENDPOINT_KEY)
    })

    it('renders the open project dialog without mounting the menu', () => {
        render(
            <ProjectOpenDialog
                branches={BRANCHES}
                isDesktopMode={false}
                isGithubAuthenticated
                isLoading={false}
                onChooseLocalFolder={vi.fn(async () => undefined)}
                projectOpenResolution={null}
                onBranchChange={vi.fn()}
                onClose={vi.fn()}
                onCreateProjectFolders={vi.fn()}
                onCreateRemoteProject={vi.fn((rootPath, branch) => ({ branch, id: rootPath, rootPath }))}
                onCreateWorkingFolder={vi.fn()}
                onDiscardGithubPendingCommits={vi.fn()}
                onLoadManualBranches={vi.fn(async () => ({ branches: BRANCHES, repository: REPOSITORIES[0] }))}
                onLoadRemoteBranches={vi.fn(async () => BRANCHES)}
